import{_ as r,c as a,o,aM as n}from"./chunks/framework.kKeYZnSg.js";const f=JSON.parse('{"title":"Other","description":"","frontmatter":{},"headers":[],"relativePath":"build-tools/package-manager/other.md","filePath":"build-tools/package-manager/other.md","lastUpdated":1785398145000}'),t={name:"build-tools/package-manager/other.md"};function l(s,e,i,p,h,m){return o(),a("div",null,e[0]||(e[0]=[n('<h1 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h1><h2 id="monorepo管理方式" tabindex="-1">monorepo管理方式 <a class="header-anchor" href="#monorepo管理方式" aria-label="Permalink to &quot;monorepo管理方式&quot;">​</a></h2><ul><li><a href="https://classic.yarnpkg.com/en/docs/workspaces" target="_blank" rel="nofollow noopener noreferrer">yarn workspaces</a></li><li><a href="https://pnpm.io/workspaces" target="_blank" rel="nofollow noopener noreferrer">pnpm workspaces</a></li><li><a href="https://nx.dev/" target="_blank" rel="nofollow noopener noreferrer">Nx</a></li><li><a href="https://lerna.js.org/" target="_blank" rel="nofollow noopener noreferrer">lerna</a></li><li><a href="https://turborepo.dev/" target="_blank" rel="nofollow noopener noreferrer">Turborepo</a></li></ul><h2 id="包管理工具的演进" tabindex="-1">包管理工具的演进 <a class="header-anchor" href="#包管理工具的演进" aria-label="Permalink to &quot;包管理工具的演进&quot;">​</a></h2><ul><li><a href="https://mp.weixin.qq.com/s/beP1bxgbTT1Z91KS3svDvw" target="_blank" rel="nofollow noopener noreferrer">https://mp.weixin.qq.com/s/beP1bxgbTT1Z91KS3svDvw</a></li><li><a href="https://mp.weixin.qq.com/s/9JCs3rCmVuGT3FvKxXMJwg" target="_blank" rel="nofollow noopener noreferrer">https://mp.weixin.qq.com/s/9JCs3rCmVuGT3FvKxXMJwg</a></li><li><a href="https://segmentfault.com/a/1190000039684460" target="_blank" rel="nofollow noopener noreferrer">https://segmentfault.com/a/1190000039684460</a></li></ul><h2 id="yarn与npm相比的主要优化" tabindex="-1">yarn与npm相比的主要优化 <a class="header-anchor" href="#yarn与npm相比的主要优化" aria-label="Permalink to &quot;yarn与npm相比的主要优化&quot;">​</a></h2><blockquote><ul><li><strong>并行安装</strong>：无论 npm 还是 yarn 在执行包的安装时，都会执行一系列任务。npm 是按照队列执行每个 package，也就是说必须要等到当前 package 安装完成之后，才能继续后面的安装。而 yarn 是同步执行所有任务，提高了性能。</li><li><strong>离线模式</strong>：如果之前已经安装过一个软件包，用 yarn 再次安装时之间从缓存中获取，就不用像 npm 那样再从网络下载了。</li><li>安装版本统一：为了防止拉取到不同的版本，yarn 有一个锁定文件 (lock file) 记录了被确切安装上的模块的版本号。每次只要新增了一个模块，yarn 就会创建（或更新）yarn.lock 这个文件。这么做就保证了，每一次拉取同一个项目依赖时，使用的都是一样的模块版本。</li><li>更好的语义化： yarn 改变了一些 npm 命令的名称，比如 yarn add/remove，比 npm 原本的 install/uninstall 要更清晰。</li></ul></blockquote>',7)]))}const d=r(t,[["render",l]]);export{f as __pageData,d as default};
